  "backup.protectionTitle": "Jak chroniona jest Twoja kopia zapasowa",
  "backup.protectionDesc": "Twoje kopie zapasowe są przechowywane w chmurze Chatyy, powiązane z Twoim kontem, i dostępne tylko po zalogowaniu. Przesyłanie między urządzeniem a naszymi serwerami odbywa się przez szyfrowane połączenie (TLS). Te kopie nie są szyfrowane end-to-end.",
